-- 2026-11-07l: MP Background timelines for batch 20, 25 more current MPs (owner's approval, "yes", 7 Nov 2026).
-- Sets background_timeline (169 entries, copied exactly from "background/background-batch20-draft.json", which is not committed) and
-- background_last_checked = 2026-11-07 for member_ids 5048, 5050, 5052, 5053, 5054, 5055, 5057, 5058, 5059, 5062, 5063, 5064, 5065, 5066, 5070, 5071, 5073, 5074, 5075, 5076, 5077, 5078, 5081, 5082, 5083,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Cowork researched every entry
-- and opened every source on 7 Nov 2026 (politics.co.uk, the Register of Members' Financial Interests of 11 Nov 2024, Wikipedia, Hansard).
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-11-07l-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 421 existing timelines are unchanged (md5);
-- MPs with a timeline go from 421 to 446; each array equals the file exactly; 5906 entries in all afterwards.
-- Undo: 2026-11-07l-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (5048, 5050, 5052, 5053, 5054, 5055, 5057, 5058, 5059, 5062, 5063, 5064, 5065, 5066, 5070, 5071, 5073, 5074, 5075, 5076, 5077, 5078, 5081, 5082, 5083)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (5048, 5050, 5052, 5053, 5054, 5055, 5057, 5058, 5059, 5062, 5063, 5064, 5065, 5066, 5070, 5071, 5073, 5074, 5075, 5076, 5077, 5078, 5081, 5082, 5083) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 421 THEN RAISE EXCEPTION 'expected 421 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
